// docs/GAME_REPORT.md, generated by scripts/game/calibrate.ts from the calibration summaries and
// the component validation. Deterministic for the same summaries.

import { evaluate, type CheckRow, type OtSoakCounts } from "./checks5c-rules";
import { evaluate5d, type Check5dRow, type Sim5dCounts } from "./checks5d-rules";

interface Row {
  id: string;
  label: string;
  unit: string;
  predicted: number;
  actual: number;
  n: number;
  lo: number;
  hi: number;
  tolerance: number | null;
  spread: [number, number];
  status: string;
}

interface Summary {
  target: string;
  actualSeasons: number[];
  tolerancesSha256: string;
  codeHash: string;
  games: number;
  leagues: number;
  gamesPerLeague: number;
  runSeed: number;
  league: { homeField: { ratingEdge: number; crowdNoise: number }; teamStrength: { sd: number } };
  invariants: { violations: number; postseasonGames: number; postseasonTies: number };
  perf: { msPerGame: number; wallSeconds: number; machine: string };
  metrics: Row[];
}

const EXPECTED: readonly { what: string; ids: readonly string[] }[] = [
  { what: "Supported flags per snap run low (step 4: 6.70% vs 7.32% in 2024-2025, 6.80% after revision 7), so accepted supported penalties per game may fail low.", ids: ["penalties.supported.perGame", "penaltyYards.supported.perGame"] },
  { what: "Step 4's accepted holdout misses (inside-run 1-3 share, play-action scrambles, extra points) and step 2's approved deviations flow into game totals; extra points and completions run low, so points may run slightly low.", ids: ["points.mean", "total.mean"] },
  { what: "Team quality spread: generated teams differ only by sampling and the designed strength spread, so margin SD may run low.", ids: ["margin.sd", "absMargin.share.22+"] },
];

const f2 = (x: number): string => x.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function table(rows: readonly Row[]): string[] {
  const out = [
    "| Metric | Predicted | Actual | n | 95% interval of actual | Tolerance | Spread across leagues | Status |",
    "|---|---|---|---|---|---|---|---|",
  ];
  for (const r of rows) {
    const tol = r.tolerance === null ? "" : `${r.tolerance} ${r.unit}`;
    out.push(`| \`${r.id}\` | ${f2(r.predicted)} | ${f2(r.actual)} | ${Math.round(r.n).toLocaleString("en-US")} | ${f2(r.lo)} to ${f2(r.hi)} | ${tol} | ${f2(r.spread[0])} to ${f2(r.spread[1])} | ${r.status} |`);
  }
  return out;
}

function section(title: string, s: Summary): string[] {
  const fails = s.metrics.filter((r) => r.status === "fail");
  const lines = [
    `## ${title}`,
    "",
    `Actual: regular-season games ${s.actualSeasons[0]}-${s.actualSeasons[s.actualSeasons.length - 1]}${s.target === "insample" ? ", season-weighted like the fits (2-season half-life anchored at 2023); home-field rows leave out 2020 and neutral sites" : ", unweighted; home-field rows leave out neutral sites"}. Predicted: ${s.games.toLocaleString("en-US")} simulated games, ${s.leagues} generated leagues x ${s.gamesPerLeague.toLocaleString("en-US")} games, run seed ${s.runSeed}, 2026 rule set. Percent rows (unit pp) are in percent. Tolerances sha256 \`${s.tolerancesSha256}\`; code hash \`${s.codeHash}\`.`,
    "",
    `League settings (designed, tuned on 2016-2023): home rating edge ${s.league.homeField.ratingEdge}, crowd noise ${s.league.homeField.crowdNoise}, team strength SD ${s.league.teamStrength.sd}. Invariant violations: ${s.invariants.violations}. Postseason soak: ${s.invariants.postseasonGames.toLocaleString("en-US")} games, ${s.invariants.postseasonTies} ties. Speed: ${s.perf.msPerGame} ms per game, ${s.perf.wallSeconds} s wall clock (${s.perf.machine}).`,
    "",
    `Gated failures: ${fails.map((r) => `\`${r.id}\``).join(", ")}.`,
    "",
    `Accepted by Joseph (known deviations in data/game/tolerances.json for this sample, 2026-11-12): ${s.metrics.filter((r) => r.status === "accepted").map((r) => `\`${r.id}\``).join(", ") || "none"}.`,
    "",
    ...table(s.metrics),
    "",
    "Expected misses, stated before the run:",
    "",
  ];
  for (const e of EXPECTED) {
    const out = e.ids.map((id) => {
      const r = s.metrics.find((x) => x.id === id);
      return r === undefined ? id : `\`${id}\` ${r.status} (${f2(r.predicted)} vs ${f2(r.actual)})`;
    });
    lines.push(`- ${e.what} Outcome: ${out.join("; ")}.`);
  }
  lines.push("");
  return lines;
}

/** Every earlier 2024-2025 game-level run, as written to this report at the time. */
const HOLDOUT_HISTORY: readonly { readonly when: string; readonly what: string; readonly fails: number }[] = [
  { when: "2026-11-11", what: "first holdout run (pre-registered tolerances, settings recorded in DECISIONS.md)", fails: 15 },
  { when: "2026-11-11", what: "after step 5 post-validation revisions 1-5 (timeout run-off, tempo and timeout levels, timeouts before kicks, onside levels)", fails: 16 },
  { when: "2026-11-11", what: "after revisions 8-13 (red-zone bins and TD flag, punt holding, box-score kicks, penalty choice, kneels, punt touchbacks)", fails: 13 },
  { when: "2026-11-12", what: "after the step 5a caller amendment (late-game score bins)", fails: 12 },
  { when: "2026-11-12", what: "after the code review fixes (box-score drive ends and wiped kicks)", fails: 12 },
];

const D4_IDS = [
  "absMargin.share.0", "absMargin.share.1-3", "absMargin.share.4-7", "absMargin.share.8-14", "absMargin.share.15-21", "absMargin.share.22+",
  "overtime.rate", "tie.rate", "onside.perGame", "fieldGoalAttempts.perGame", "fourthDownGo.perGame", "punts.perGame",
  "driveResult.share.touchdown", "driveResult.share.fieldGoal", "driveResult.share.missedFieldGoal", "driveResult.share.punt", "driveResult.share.turnover",
  "driveResult.share.downs", "driveResult.share.endOfHalf", "driveResult.share.safety", "points.mean", "total.mean", "margin.sd", "homeMargin.mean", "homeWin.rate",
];

/** Step 5a D2, D3 and D4: late field-goal diagnostics and the in-sample before/after table. */
function step5aSection(s: Summary & { diagnostics?: Record<string, { predicted: number; actual: number | null; n: number }> }, pre: { metrics: { id: string; predicted: number; actual: number }[] } | undefined, accepted: ReadonlySet<string> = new Set()): string[] {
  const d = s.diagnostics;
  if (d === undefined) return [];
  const out = ["### Step 5a late-game diagnostics (in-sample, not gated)", "",
    "4th-down field goal rate in Q4 with 5:00 or less inside the opponent's 37, and field goal attempts in the final 2:00 of Q4 per game, by the offense's score. D3 checks (data/caller/latechecks.json): rate within 10 pp, attempts within 0.02 per game. Step 5b C3 rows (`diag.timeoutRate`): timeout rate per scrimmage dead ball by side, the calling team's score and window, sim against real 2016-2023, the C7 2 pp threshold where real n >= 100.", "",
    "| Diagnostic | Sim | Real | Real n | Check |", "|---|---|---|---|---|"];
  for (const [id, v] of Object.entries(d)) {
    if (id.startsWith("diag.timeoutsPerTeamGame")) continue; // C3 per team-game: COACH_REPORT.md
    const to = id.startsWith("diag.timeoutRate");
    const rate = id.startsWith("diag.late4th") || to;
    const sim = rate ? 100 * v.predicted : v.predicted;
    const real = v.actual === null ? null : rate ? 100 * v.actual : v.actual;
    // D3 (5a): 10 pp and 0.02 kicks a game. C3 (5b): the C7 timeout threshold, 2 pp, where n >= 100.
    const tol = to ? 2 : rate ? 10 : 0.02;
    const raw = real === null ? "-" : to && v.n < 100 ? "n below 100" : Math.abs(sim - real) <= tol + 1e-9 ? "pass" : "fail";
    // An in-sample known deviation approved by Joseph (data/game/tolerances.json, scope insample).
    const ok = raw === "fail" && accepted.has(id) ? "accepted" : raw;
    out.push(`| \`${id}\` | ${rate ? f2(sim) + "%" : sim.toFixed(3)} | ${real === null ? "-" : rate ? f2(real) + "%" : real.toFixed(3)} | ${v.n.toLocaleString("en-US")} | ${ok} |`);
  }
  out.push("");
  if (pre !== undefined) {
    out.push("### Step 5a before and after (in-sample, same league seeds)", "", "Before: after step 5 fixes 1-5, before the caller amendment (data/game/calibration.insample.pre5a.json). After: this run.", "",
      "| Metric | Before | After | Actual |", "|---|---|---|---|");
    for (const id of D4_IDS) {
      const a = s.metrics.find((r) => r.id === id);
      const b = pre.metrics.find((r) => r.id === id);
      if (a !== undefined && b !== undefined) out.push(`| \`${id}\` | ${f2(b.predicted)} | ${f2(a.predicted)} | ${f2(a.actual)} |`);
    }
    out.push("");
  }
  return out;
}

export interface Step5bInputs {
  /** In-sample stage runs (F1): baseline, after B, after C. After D is after C: D was not built (A no-go). */
  readonly stages?: undefined | { readonly callerRegressions?: { note: string; rows: { row: string; predicted: number; actual: number; step2: number; pre5b: number; after5b: number }[] }; readonly order: readonly string[]; readonly labels: Readonly<Record<string, string>>; readonly runs: Readonly<Record<string, { metrics: { id: string; predicted: number; actual: number; status: string }[]; extras: Record<string, number> }>> };
  /** Metrics Joseph accepted in-sample (data/game/tolerances.json known_deviations, scope insample). */
  readonly acceptedInSample?: undefined | readonly string[];
  /** B10 (data/game/late-backoff.json). */
  readonly lateBackoff?: undefined | { games: number; lateLookups: number; rows: { factor: string; level: number; dims: string[]; key: string; lateTime: string; score: string; lookups: number; b9a: number; b9b: number }[] };
  /** E (data/game/investigations.json and investigations.real.json). */
  readonly investigations?: undefined | { sim: { games: number; counts: Record<string, number> }; real: { games: number; counts: Record<string, number> } };
}

const EXTRA_LABELS: Readonly<Record<string, string>> = {
  exact3: "Exact 3-point final margin, share of games",
  otEndingOn3: "Overtime games ending on a 3-point margin, share",
  leaderStopG5: "Leader's clock-stopping snap share, Q4 5:00 to 2:01",
  leaderStopGF: "Leader's clock-stopping snap share, final 2:00",
  drivesStartingFinal2PerGame: "Drives starting in the final 2:00 of Q4, per game",
};

/** Step 5b F1, B10 and E. Report only. */
export function step5bSection(inp: Step5bInputs): string[] {
  const out: string[] = [];
  const st = inp.stages;
  if (st !== undefined) {
    out.push("### Step 5b before and after (F1, in-sample, same seeds)", "",
      `Stages: ${st.order.map((k) => `${k} = ${st.labels[k]}`).join("; ")}. Milestone D (out-of-bounds layer) was not built: A's counterfactual was a no-go (docs/DECISIONS.md), so "after D" equals "after C". Every gated metric, then the F1 extras (sim only).`, "",
      `| Metric | ${st.order.join(" | ")} | Actual | Status ${st.order.join(" / ")} |`, `|---|${st.order.map(() => "---|").join("")}---|---|`);
    const first = st.runs[st.order[0] as string];
    for (const r of first?.metrics ?? []) {
      const cells = st.order.map((k) => st.runs[k]?.metrics.find((m) => m.id === r.id));
      out.push(`| \`${r.id}\` | ${cells.map((c) => (c === undefined ? "-" : f2(c.predicted))).join(" | ")} | ${f2(r.actual)} | ${cells.map((c) => c?.status ?? "-").join(" / ")} |`);
    }
    for (const [id, label] of Object.entries(EXTRA_LABELS)) {
      const pct = id !== "drivesStartingFinal2PerGame";
      out.push(`| ${label} | ${st.order.map((k) => { const v = st.runs[k]?.extras[id]; return v === undefined ? "-" : pct ? f2(100 * v) + "%" : f2(v); }).join(" | ")} | - | not gated |`);
    }
    out.push("");
    const cr = st.callerRegressions;
    if (cr !== undefined) {
      out.push(`B11 (caller): ${cr.note}`, "", "| 8b row, 2016-2023 | Predicted | Actual | Gap, step 2 | Gap, before 5b | Gap, after 5b |", "|---|---|---|---|---|---|");
      const g = (x: number): string => (x > 0 ? "+" : "") + x.toFixed(1);
      for (const r of cr.rows) out.push(`| ${r.row} | ${r.predicted.toFixed(1)}% | ${r.actual.toFixed(1)}% | ${g(r.step2)} | ${g(r.pre5b)} | ${g(r.after5b)} |`);
      out.push("");
    }
  }
  const lb = inp.lateBackoff;
  if (lb !== undefined) {
    const a = lb.rows.reduce((n, r) => n + r.b9a, 0);
    const b = lb.rows.reduce((n, r) => n + r.b9b, 0);
    const total = lb.rows.reduce((n, r) => n + r.lookups, 0);
    out.push("### Step 5b late cells past the last score-aware level (B10)", "",
      `Every late-window caller cell (G5, GF, overtime) the sim reaches whose lookup backs off past the factor's last level with a score dimension, with its lookup count over the in-sample run (${lb.games.toLocaleString("en-US")} games, ${lb.lateLookups.toLocaleString("en-US")} late scrimmage snaps; \`scripts/game/late-backoff.ts\`). ${lb.rows.length} cells, ${total.toLocaleString("en-US")} lookups. B9 cell (a) lookups on this list: ${a}; cell (b): ${b}.`, "",
      "| Factor | Level | Dims | Key | Window | Late score | Lookups |", "|---|---|---|---|---|---|---|");
    for (const r of lb.rows) out.push(`| ${r.factor} | ${r.level} | ${r.dims.join(", ") || "(global)"} | \`${r.key}\` | ${r.lateTime} | ${r.score} | ${r.lookups.toLocaleString("en-US")} |`);
    out.push("");
  }
  const inv = inp.investigations;
  if (inv !== undefined) {
    const { sim, real } = inv;
    const per = (c: Record<string, number>, g: number, k: string): number => (c[k] ?? 0) / g;
    const share = (c: Record<string, number>, k: string, n: string): number => (c[k] ?? 0) / Math.max(1, c[n] ?? 0);
    const pct = (x: number): string => f2(100 * x) + "%";
    out.push("### Step 5b investigations (E, report only)", "",
      `Sim: the in-sample run's ${sim.games.toLocaleString("en-US")} games (\`scripts/game/investigate.ts\`). Real: ${real.games.toLocaleString("en-US")} regular-season games 2016-2023, unweighted (\`pipeline/game/investigate.py\`). Regulation snaps only. The measures are designed proxies computed the same way on both sides; see pipeline/game/investigate.py. Nothing here changed a table, config or sim code (E3).`, "",
      "E1: safeties and the own 1-5.", "", "| Measure | Sim | Real |", "|---|---|---|");
    for (const k of ["safety.cause.sack", "safety.cause.run", "safety.cause.other", "safety.spot.own1-5", "safety.spot.own6-10", "safety.spot.other", "own1-5.snaps"]) {
      out.push(`| ${k} per game | ${per(sim.counts, sim.games, k).toFixed(4)} | ${per(real.counts, real.games, k).toFixed(4)} |`);
    }
    for (const c of ["run", "pass", "kneel", "spike", "punt", "fieldGoal"]) {
      out.push(`| Own 1-5, downs 1-3: ${c} share | ${pct(share(sim.counts, `own1-5.call.${c}`, "own1-5.calls"))} | ${pct(share(real.counts, `own1-5.call.${c}`, "own1-5.calls"))} |`);
    }
    out.push("", "E2: dropback and incompletion share per run or pass snap, by the offense's score and time.", "",
      "| Score | Time | Sim snaps | Real snaps | Dropback sim | Dropback real | Incompletion sim | Incompletion real |", "|---|---|---|---|---|---|---|---|");
    for (const s3 of ["T", "0", "L"]) {
      for (const t5 of ["H1", "H1F", "H2", "G5", "GF"]) {
        const cell = `${s3}.${t5}`;
        out.push(`| ${s3} | ${t5} | ${(sim.counts[`snaps.${cell}`] ?? 0).toLocaleString("en-US")} | ${(real.counts[`snaps.${cell}`] ?? 0).toLocaleString("en-US")} | ${pct(share(sim.counts, `dropback.${cell}`, `snaps.${cell}`))} | ${pct(share(real.counts, `dropback.${cell}`, `snaps.${cell}`))} | ${pct(share(sim.counts, `incompletion.${cell}`, `snaps.${cell}`))} | ${pct(share(real.counts, `incompletion.${cell}`, `snaps.${cell}`))} |`);
      }
    }
    out.push("", "E2: how run or pass snaps in the last 5:00 of Q4 end, sim / real. \"None\" means none of the four; the sim's actual clock-stopped share is shown for reference.", "",
      "| Score | Time | Incompletion | Out of bounds | Timeout | Other | None | Sim clock stopped |", "|---|---|---|---|---|---|---|---|");
    for (const s3 of ["T", "0", "L"]) {
      for (const t5 of ["G5", "GF"]) {
        const n = `stop.${s3}.${t5}.snaps`;
        const cells = ["incompletion", "outOfBounds", "timeout", "other", "none"].map((w) => `${pct(share(sim.counts, `stop.${s3}.${t5}.${w}`, n))} / ${pct(share(real.counts, `stop.${s3}.${t5}.${w}`, n))}`);
        out.push(`| ${s3} | ${t5} | ${cells.join(" | ")} | ${pct(share(sim.counts, `stop.${s3}.${t5}.clockStopped`, n))} |`);
      }
    }
    out.push("");
  }
  return out;
}

/** Step 5c: the pre-registered checks, sim runs by label (data/game/checks5c.sim.json) vs real 2016-2023. */
export interface Step5cInputs {
  readonly real: { readonly counts: Readonly<Record<string, number>> };
  readonly sim: { readonly runs: Readonly<Record<string, { readonly label: string; readonly games: number; readonly counts: Readonly<Record<string, number>>; readonly byLeague: readonly Readonly<Record<string, number>>[]; readonly ot: OtSoakCounts | null }>> };
  /** Labels in order with what each stands for. */
  readonly order: readonly (readonly [string, string])[];
  /** The designed late try chart's cells (data/caller/config.json `tryChart`), "window|score" -> call. */
  readonly chart?: Readonly<Record<string, string>>;
  /** Checks Joseph accepted as misses (data/game/step5c-accepted.json); a failing one reads "accepted". */
  readonly accepted?: readonly string[];
}

const MARGIN_KEYS: readonly (readonly [string, string])[] = [["margin.1-3", "absMargin 1-3"], ["margin.8-14", "absMargin 8-14"], ["margin.exact3", "exact 3"]];

export function step5cSection(inp: Step5cInputs | undefined): string[] {
  if (inp === undefined) return [];
  const runs = inp.order.filter(([k]) => inp.sim.runs[k] !== undefined);
  if (runs.length === 0) return [];
  const fmt = (r: CheckRow, v: number | null): string => (v === null || Number.isNaN(v) ? "-" : r.unit === "pp" ? `${f2(v)}%` : r.unit === "count" ? String(v) : v.toFixed(4));
  const evals = runs.map(([k]) => evaluate(inp.sim.runs[k] as NonNullable<(typeof inp.sim.runs)[string]>, inp.real.counts));
  const out = ["### Step 5c pre-registered checks (data/game/step5c-checks.json)", "",
    `Sim: the in-sample run's games (\`scripts/game/checks5c.ts\`), plus the c.ot.complete postseason soak (league 4242, seeds 1-10,000). Real: ${(inp.real.counts["games"] ?? 0).toLocaleString("en-US")} regular-season games 2016-2023, unweighted, timeouts in clock order (\`pipeline/game/checks5c.py\`). Runs: ${runs.map(([k, w]) => `${k} = ${w}`).join("; ")}.`, "",
    `| Check | ${runs.map(([k]) => k).join(" | ")} | Real | Rule | ${runs.map(([k]) => k).join(" / ")} |`, `|---|${runs.map(() => "---|").join("")}---|---|---|`];
  const first = evals[0] as CheckRow[];
  first.forEach((r, i) => {
    const cells = evals.map((e) => e[i] as CheckRow);
    const st = (c: CheckRow, last: boolean): string => (c.pass ? "pass" : last && (inp.accepted ?? []).includes(c.id) ? "accepted" : "fail");
    out.push(`| \`${r.id}\` | ${cells.map((c) => fmt(c, c.sim)).join(" | ")} | ${fmt(r, r.real)} | ${r.rule} | ${cells.map((c, j) => st(c, j === cells.length - 1)).join(" / ")} |`);
  });
  out.push("", "Reported, not gated: final margins (share of games, with the spread across the 10 league seeds), overtime games ending on 3, and Q4 ending on a run-off by a 1-8 trailer holding timeouts (sim only).", "",
    `| Measure | ${runs.map(([k]) => k).join(" | ")} | Real |`, `|---|${runs.map(() => "---|").join("")}---|`);
  const pc = (c: Readonly<Record<string, number>>, k: string, d: string): number => (100 * (c[k] ?? 0)) / Math.max(1, c[d] ?? 0);
  for (const [k, lab] of MARGIN_KEYS) {
    const cells = runs.map(([r]) => {
      const run = inp.sim.runs[r] as NonNullable<(typeof inp.sim.runs)[string]>;
      const sp = run.byLeague.map((b) => pc(b, k, "games"));
      return `${f2(pc(run.counts, k, "games"))}% (${f2(Math.min(...sp))} to ${f2(Math.max(...sp))})`;
    });
    out.push(`| ${lab} | ${cells.join(" | ")} | ${f2(pc(inp.real.counts, k, "games"))}% |`);
  }
  const simOnly = (k: string, d: string): string[] => runs.map(([r]) => `${f2(pc((inp.sim.runs[r] as NonNullable<(typeof inp.sim.runs)[string]>).counts, k, d))}%`);
  out.push(`| OT games ending on 3 | ${simOnly("ot.endsOn3", "ot.games").join(" | ")} | ${f2(pc(inp.real.counts, "ot.endsOn3", "ot.games"))}% |`);
  out.push(`| Q4 ends on a 1-8 trailer's run-off with timeouts | ${simOnly("trail.endsOnRunoff", "games").join(" | ")} | - |`);
  const otPer = runs.map(([r]) => {
    const o = (inp.sim.runs[r] as NonNullable<(typeof inp.sim.runs)[string]>).ot as (OtSoakCounts & { otGames?: number; otPeriods?: number }) | null;
    return o === null || o.otGames === undefined || o.otGames === 0 ? "-" : f2((o.otPeriods ?? 0) / o.otGames);
  });
  out.push(`| Postseason periods played per OT game (soak) | ${otPer.join(" | ")} | - |`, "");
  // C4: try choice by score after the touchdown in the final 5:00 of Q4, last run vs real, with n.
  const [lastKey, lastWhat] = runs[runs.length - 1] as readonly [string, string];
  const last = (inp.sim.runs[lastKey] as NonNullable<(typeof inp.sim.runs)[string]>).counts;
  const rc = inp.real.counts;
  if (Object.keys(last).some((k) => k.startsWith("try.cell."))) {
    out.push(`C4: two-point share of 4th-quarter tries in the final 5:00 by the scoring team's score after the touchdown, sim (run ${lastKey}, ${lastWhat}) vs real 2016-2023 (two-point tries / tries). Not gated. The designed chart (data/caller/config.json \`tryChart\`) decides the cells marked "chart".`, "",
      "| Window | Score | Sim | Real | Chart |", "|---|---|---|---|---|");
    for (const w of ["G5", "GF"]) {
      for (let d = -8; d <= 8; d++) {
        const k = `try.cell.${w}.${d}`;
        const cell = (c: Readonly<Record<string, number>>): string => `${c[`${k}.two`] ?? 0}/${c[`${k}.tries`] ?? 0}`;
        out.push(`| ${w} | ${d > 0 ? `+${d}` : d} | ${cell(last)} | ${cell(rc)} | ${inp.chart?.[`${w}|${d}`] ?? "fitted"} |`);
      }
    }
    out.push("");
  }
  return out;
}

export interface Step5dInputs {
  readonly real: { readonly counts: Readonly<Record<string, number>> };
  readonly sim: { readonly runs: Readonly<Record<string, Sim5dCounts & { readonly games: number; readonly byLeague: readonly Readonly<Record<string, number>>[] }>> };
  /** The 5c checks re-measured on each 5d run (data/game/checks5c.sim.json, labels "5d.<run>"). */
  readonly sim5c?: { readonly runs: Readonly<Record<string, { readonly counts: Readonly<Record<string, number>>; readonly ot: OtSoakCounts | null }>> };
  readonly real5c?: { readonly counts: Readonly<Record<string, number>> };
  /** In-sample game metrics per run (data/game/calibration.insample.stages5d.json). */
  readonly stages?: Readonly<Record<string, { readonly what: string; readonly msPerGame: number; readonly metrics: readonly { readonly id: string; readonly predicted: number; readonly actual: number; readonly tolerance: number | null; readonly status: string; readonly spread: readonly [number, number] }[] }>>;
  /** Labels in order with what each stands for. */
  readonly order: readonly (readonly [string, string])[];
  /** 5d checks Joseph accepted as misses (data/game/step5d-accepted.json); a failing one reads "accepted" on the last run. */
  readonly accepted?: readonly string[];
  /** Joseph's accepted 5c values (data/game/step5c-accepted.json, `observed`): the at-or-better reference where present. */
  readonly accepted5c?: Readonly<Record<string, number>>;
}

/** 5c checks that fail at run H and stay accepted only at or better than their run H value (spec, No regression). */
export const STEP5C_AT_OR_BETTER: Readonly<Record<string, number>> = { "c.kneel.ballBack": 8.97, "c.fg.63": 0.0254, "c.fg.50to59": 0.764 };

export function step5dSection(inp: Step5dInputs | undefined): string[] {
  if (inp === undefined) return [];
  const runs = inp.order.filter(([k]) => inp.sim.runs[k] !== undefined);
  if (runs.length === 0) return [];
  const fmt = (unit: string, v: number | null): string => (v === null || Number.isNaN(v) ? "-" : unit === "pp" ? `${f2(v)}%` : unit === "count" ? String(v) : v.toFixed(4));
  const evals = runs.map(([k]) => evaluate5d(inp.sim.runs[k] as NonNullable<(typeof inp.sim.runs)[string]>, inp.real.counts));
  const head = runs.map(([k]) => k);
  const out = ["### Step 5d pre-registered checks (data/game/step5d-checks.json)", "",
    `Sim: the in-sample run's games (\`scripts/game/checks5d.ts\`); d.try.otDown2 adds the league 4242 postseason soak (seeds 1-10,000). Real: ${(inp.real.counts["games"] ?? 0).toLocaleString("en-US")} regular-season games 2016-2023, unweighted, rows in clock order (\`pipeline/game/checks5d.py\`; definitions in its docstring). Runs: ${runs.map(([k, w]) => `${k} = ${w}`).join("; ")}.`, "",
    `| Check | ${head.join(" | ")} | Real | Rule | ${head.join(" / ")} |`, `|---|${runs.map(() => "---|").join("")}---|---|---|`];
  (evals[0] as Check5dRow[]).forEach((r, i) => {
    const cells = evals.map((e) => e[i] as Check5dRow);
    const st = (c: Check5dRow, last: boolean): string => (!c.gated ? "reported" : c.pass ? "pass" : last && (inp.accepted ?? []).includes(c.id) ? "accepted" : "fail");
    out.push(`| \`${r.id}\` | ${cells.map((c) => fmt(c.unit, c.sim)).join(" | ")} | ${fmt(r.unit, r.real)} | ${r.rule} | ${cells.map((c, j) => st(c, j === cells.length - 1)).join(" / ")} |`);
  });
  const lastRows = evals[evals.length - 1] as Check5dRow[];
  out.push("", `n (sim / real) at run ${head[head.length - 1]}: ${lastRows.map((r) => `\`${r.id}\` ${r.n}`).join("; ")}.`, "");
  // Reported, not gated.
  const pc = (c: Readonly<Record<string, number>>, k: string, d: string): number => (100 * (c[k] ?? 0)) / Math.max(1, c[d] ?? 0);
  const per = (c: Readonly<Record<string, number>>, k: string): number => (c[k] ?? 0) / Math.max(1, c["games"] ?? 0);
  const run = (k: string): NonNullable<(typeof inp.sim.runs)[string]> => inp.sim.runs[k] as NonNullable<(typeof inp.sim.runs)[string]>;
  const rc = inp.real.counts;
  out.push("Reported, not gated (per game unless a share; margins with the spread across the 10 league seeds).", "", `| Measure | ${head.join(" | ")} | Real |`, `|---|${runs.map(() => "---|").join("")}---|`);
  const perRow = (lab: string, k: string): void => {
    out.push(`| ${lab} | ${runs.map(([r]) => per(run(r).counts, k).toFixed(4)).join(" | ")} | ${per(rc, k).toFixed(4)} |`);
  };
  perRow("Spikes, all periods", "spike.all");
  perRow("Late spikes by 1-8 trailers holding 1+ timeouts", "spike.trail1TO");
  out.push(`| Gaps of 15 s+ in the final 2:00, 1-8 trailer with 0 timeouts | ${runs.map(([r]) => `${f2(pc(run(r).counts, "gap.trail0TO.final2.hits", "gap.trail0TO.final2.gaps"))}%`).join(" | ")} | ${f2(pc(rc, "gap.trail0TO.final2.hits", "gap.trail0TO.final2.gaps"))}% |`);
  perRow("Late kneels, not leading, > 0:47: trailing 1-8", "kneel.notLeading.trail1to8");
  perRow("Late kneels, not leading, > 0:47: trailing 9+", "kneel.notLeading.trail9");
  perRow("Late kneels, not leading, > 0:47: tied", "kneel.notLeading.tied");
  for (const [k, lab] of [["margin.0", "absMargin 0"], ["margin.1-3", "absMargin 1-3"], ["margin.4-7", "absMargin 4-7"], ["margin.8-14", "absMargin 8-14"], ["margin.15-21", "absMargin 15-21"], ["margin.22+", "absMargin 22+"], ["margin.exact3", "exact 3"]] as const) {
    const cells = runs.map(([r]) => {
      const sp = run(r).byLeague.map((b) => pc(b, k, "games"));
      return `${f2(pc(run(r).counts, k, "games"))}% (${f2(Math.min(...sp))} to ${f2(Math.max(...sp))})`;
    });
    out.push(`| ${lab} | ${cells.join(" | ")} | ${f2(pc(rc, k, "games"))}% |`);
  }
  out.push("");
  // E4 (reported): overtime tries by otBothPossessed and score after the touchdown, last run vs real.
  {
    const [lastK] = runs[runs.length - 1] as readonly [string, string];
    const lr = run(lastK);
    const simCells: Record<string, number> = {};
    for (const src of [lr.counts, lr.ot?.cells ?? {}]) for (const [k, v] of Object.entries(src)) if (k.startsWith("ottry.")) simCells[k] = (simCells[k] ?? 0) + v;
    const keys = new Set([...Object.keys(simCells), ...Object.keys(rc).filter((k) => k.startsWith("ottry."))].map((k) => k.split(".").slice(1, 3).join(".")));
    const sorted = [...keys].sort((a, b) => {
      const [fa, sa] = a.split(".").map(Number) as [number, number];
      const [fb, sb] = b.split(".").map(Number) as [number, number];
      return fa - fb || sa - sb;
    });
    out.push(`E4: overtime tries by \`otBothPossessed\` (the flag) and the scoring team's score after the touchdown; sim = run ${lastK}'s in-sample overtime plus the league 4242 postseason soak (seeds 1-10,000), real = 2016-2023 regular season (no regular-season overtime try then). Two-point tries / tries.`, "",
      "| Overtime try | Flag | Score | Sim | Real |", "|---|---|---|---|---|");
    for (const k of sorted) {
      const [f, sc] = k.split(".") as [string, string];
      const cell = (c: Readonly<Record<string, number>>): string => `${c[`ottry.${k}.two`] ?? 0}/${c[`ottry.${k}.tries`] ?? 0}`;
      out.push(`| otBothPossessed | ${f} | ${Number(sc) > 0 ? `+${sc}` : sc} | ${cell(simCells)} | ${cell(rc)} |`);
    }
    if (sorted.length === 0) out.push("| otBothPossessed | - | - | 0/0 | 0/0 |");
    out.push("");
  }
  // No regression of the 5c checks.
  if (inp.sim5c !== undefined && inp.real5c !== undefined) {
    const r5 = runs.filter(([k]) => inp.sim5c?.runs[`5d.${k}`] !== undefined);
    if (r5.length > 0) {
      const real5c = (inp.real5c as { counts: Readonly<Record<string, number>> }).counts;
      const ev = r5.map(([k]) => evaluate(inp.sim5c?.runs[`5d.${k}`] as NonNullable<NonNullable<Step5dInputs["sim5c"]>["runs"][string]>, real5c));
      // Exact run H values from the 5c run file when present (the spec's rounded values otherwise).
      const runHRows = inp.sim5c.runs["H"] === undefined ? [] : evaluate(inp.sim5c.runs["H"], real5c);
      // Joseph's accepted value (step5c-accepted.json) is the reference where it exists; else run H's.
      const runHOf = (id: string): number | undefined =>
        STEP5C_AT_OR_BETTER[id] === undefined ? undefined : (inp.accepted5c?.[id] ?? runHRows.find((x) => x.id === id)?.sim ?? STEP5C_AT_OR_BETTER[id]);
      out.push("No regression of the step 5c checks (data/game/step5c-checks.json, sha256 `2c9f4591…`): the 14 that pass at 5c run H must pass; `c.kneel.ballBack`, `c.fg.63` and `c.fg.50to59` must stay at or better than their run H values (|sim - real| no larger).", "",
        `| Check | ${r5.map(([k]) => k).join(" | ")} | Real | Rule | ${r5.map(([k]) => k).join(" / ")} |`, `|---|${r5.map(() => "---|").join("")}---|---|---|`);
      (ev[0] as CheckRow[]).forEach((r, i) => {
        const cells = ev.map((e) => e[i] as CheckRow);
        const runH = runHOf(r.id);
        const st = (c: CheckRow): string => {
          if (c.pass) return "pass";
          if (runH === undefined || c.real === null) return "fail";
          return Math.abs(c.sim - c.real) <= Math.abs(runH - c.real) + 1e-9 ? "accepted, at or better" : "worse than accepted";
        };
        const rule = runH === undefined ? r.rule : `${r.rule}; accepted at ${fmt(r.unit, runH)}`;
        out.push(`| \`${r.id}\` | ${cells.map((c) => fmt(c.unit, c.sim)).join(" | ")} | ${fmt(r.unit, r.real)} | ${rule} | ${cells.map(st).join(" / ")} |`);
      });
      out.push("");
    }
  }
  // Before/after: in-sample game metrics by run.
  const st = inp.stages;
  if (st !== undefined) {
    const sr = runs.filter(([k]) => st[k] !== undefined);
    if (sr.length > 0) {
      const ids = (st[(sr[0] as readonly [string, string])[0]] as NonNullable<typeof st[string]>).metrics.filter((m) => m.tolerance !== null).map((m) => m.id);
      const close = ids.filter((id) => sr.some(([k]) => {
        const m = (st[k] as NonNullable<typeof st[string]>).metrics.find((x) => x.id === id);
        return m !== undefined && m.tolerance !== null && (m.status !== "pass" || Math.abs(m.predicted - m.actual) >= 0.7 * m.tolerance);
      }));
      out.push(`In-sample gated game metrics by run: every row that is not a pass in some run, or within 30% of its tolerance (|predicted - actual| at least 0.7 x tolerance). Values are predicted (status). ${sr.map(([k]) => `${k}: ${(st[k] as NonNullable<typeof st[string]>).metrics.filter((m) => m.status === "fail").length} gated failures, ${(st[k] as NonNullable<typeof st[string]>).msPerGame} ms per game`).join("; ")}.`, "",
        `| Metric | Actual | Tolerance | ${sr.map(([k]) => k).join(" | ")} |`, `|---|---|---|${sr.map(() => "---|").join("")}`);
      for (const id of close) {
        const ms = sr.map(([k]) => (st[k] as NonNullable<typeof st[string]>).metrics.find((x) => x.id === id));
        const a = ms.find((m) => m !== undefined);
        if (a === undefined) continue;
        out.push(`| \`${id}\` | ${f2(a.actual)} | ${a.tolerance} | ${ms.map((m) => (m === undefined ? "-" : `${f2(m.predicted)} (${m.status})`)).join(" | ")} |`);
      }
      out.push("");
    }
  }
  return out;
}

export function renderReport(summaries: Readonly<Record<string, Summary>>, coach: { holdout?: { metrics: Row[] }; inSample?: { metrics: Row[] } }, pre?: { metrics: { id: string; predicted: number; actual: number }[] }, step5b: Step5bInputs = {}, step5c?: Step5cInputs, step5d?: Step5dInputs): string {
  const lines = [
    "# Game calibration report (M1 step 5)",
    "",
    "Generated by `node --import ./scripts/engine/register.mjs scripts/game/calibrate.ts --target insample|holdout`. Do not edit by hand. Metric definitions: docs/MODEL.md, Calibration (full games). Coach decision tables and their component validation: docs/COACH_REPORT.md.",
    "",
    "Disclosure: every 2024-2025 run below is post hoc. A first holdout run was made on 2026-11-11 (15 gated failures); the lead then directed fixes found on the in-sample run (step 5 post-validation revisions 1-13, the step 5a caller amendment and the step 5b amendment, docs/specs/m1-step5b-late-game-and-clock-control.md; docs/DECISIONS.md), and the holdout was rerun after them, once per change. Tolerances and known deviations are unchanged.",
    "",
  ];
  if (summaries["insample"] !== undefined) {
    lines.push(...section("1. In-sample check, 2016-2023 (run first)", summaries["insample"]));
    lines.push(...step5aSection(summaries["insample"], pre, new Set(step5b.acceptedInSample ?? [])));
    lines.push(...step5bSection(step5b));
    lines.push(...step5cSection(step5c));
    lines.push(...step5dSection(step5d));
  }
  lines.push("Every 2024-2025 game-level run so far, with its gated failures:", "");
  for (const h of HOLDOUT_HISTORY) lines.push(`- ${h.when}, ${h.what}: ${h.fails} gated failures (post hoc after the first).`);
  if (summaries["holdout"] !== undefined) {
    const n = summaries["holdout"].metrics.filter((r) => r.status === "fail").length;
    lines.push("- 2026-11-12, step 5b run 1, after the step 5b amendment (docs/specs/m1-step5b-late-game-and-clock-control.md: late caller levels and timeout levels), before the caller's key-only gate change: 12 gated failures (post hoc).");
    lines.push("- 2026-11-12, step 5b run 2, after the key-only gate change (lookups identical; recomputed because the summary pins the caller files): 12 gated failures, every metric identical to run 1 (post hoc).");
    lines.push("- 2026-11-12, step 5b run 3, after the code review's box-score first-down fix (no gated metric uses first downs), the C3 per-team-game diagnostic and the run labels: 12 gated failures, every gated metric identical to runs 1 and 2 (post hoc).");
    lines.push("- 2026-11-12, step 5b run 4, after the caller's o4Top late levels were moved after the score3 levels (post-fit, approved by Joseph): 13 gated failures (post hoc).");
    lines.push("- 2026-11-12, step 5b run 5, after Joseph accepted the remaining misses (scoped known deviations in data/game/tolerances.json): 0 gated failures, 13 accepted, every metric identical to run 4 (post hoc). Its speed reading (95 ms per game) was taken at load average about 40 and is not usable.");
    lines.push("- 2026-11-12, step 5b run 6, a speed remeasure on a quieter machine and the run label only: 0 gated failures, every metric identical to run 5 (post hoc).");
    lines.push("- 2026-11-12, step 5b run 7, after a change to this report's layout only (the gated-failure line lists accepted misses separately) and to the in-sample F1 stages: 0 gated failures, every metric identical to run 6 (post hoc).");
    lines.push("- 2026-11-12, step 5c, counted as step 5b run 8 in docs/DECISIONS.md, after every step 5c change (docs/specs/m1-step5c-playtest-fixes.md, revision 1 and milestones A-G) and Joseph's step 5c approvals: 2 gated failures (homeWin.rate, fieldGoalAttempts.perGame), and 3 accepted misses wider (post hoc).");
    lines.push("- 2026-11-12, step 5c, counted as step 5b run 9 in docs/DECISIONS.md, approvals and timing only, metrics must match run 8: after Joseph accepted run 8's five misses (scoped known deviations), on an idle machine: 0 gated failures, every metric identical to run 8 (post hoc).");
    lines.push("- 2026-11-12, step 5c, counted as step 5b run 10 in docs/DECISIONS.md, pins only, metrics must match run 9: after the code review fixes (text, a config move, C7 run 6), on an idle machine: 0 gated failures (post hoc).");
    lines.push("- 2026-11-13, step 5d, counted as step 5b run 11 in docs/DECISIONS.md, after every step 5d change (docs/specs/m1-step5d-clock-fixes.md, milestones A-E and resolution 3) and Joseph's step 5d approvals: 0 gated failures, 3 accepted misses wider (post hoc).");
    lines.push("- 2026-11-13, step 5d, counted as step 5b run 12 in docs/DECISIONS.md, approvals and pins only, metrics must match run 11: Joseph's step 5d holdout known deviations and C7 run 8: 0 gated failures (post hoc; its speed reading was taken on a loaded machine).");
    lines.push("- 2026-11-13, step 5d, counted as step 5b run 13 in docs/DECISIONS.md, after the step 5d code review and spec check fixes, Joseph's rerun acceptances and C7 run 9: 1 gated failure (points.share.38+) and 2 accepted misses wider (post hoc).");
    lines.push(`- 2026-11-13, step 5d, counted as step 5b run 14 in docs/DECISIONS.md (the run in section 2), approvals, report fix and pins only, metrics must match run 13: Joseph's run 13 holdout acceptances, the gated-failure line's backticks and C7 run 10: ${n} gated failures (post hoc).`);
  }
  lines.push("");
  if (summaries["holdout"] !== undefined) lines.push(...section("2. Validation, 2024-2025 (holdout)", summaries["holdout"]));
  else lines.push("## 2. Validation, 2024-2025 (holdout)", "", "Not run yet.", "");
  for (const [key, title] of [["inSample", "in-sample"], ["holdout", "2024-2025"]] as const) {
    const c = coach[key];
    if (c === undefined) continue;
    const fails = c.metrics.filter((m) => m.status === "fail").map((m) => `\`${m.id}\``);
    lines.push(`Component validation (C7), ${title}: ${c.metrics.length} metrics, gated failures: ${fails.length === 0 ? "none" : fails.join(", ")}.`, "");
  }
  return lines.join("\n").replace(/\n+$/, "") + "\n";
}
